@-moz-document domain("syosetu.com") {
/* ============================================================
     Syosetu (Narou) Dark
     The Syosetu network shares one frontend across the portal
     (syosetu.com), the novel reader (ncode/novel18.syosetu.com),
     the ranking/search site (yomou.syosetu.com) and mypage. Most
     colors are hardcoded per element, but the modern components
     also read a few :root design tokens — those are remapped below
     so every surface painted through them follows. Priorities: a
     calm reading surface for long-form Japanese text (soft
     off-white body on a dark bg, never glare), opaque sticky reader
     header/menu, legible chapter nav and font/bookmark controls,
     and the signature Narou brown + ranking medal colors refined
     for dark. Layout/typography untouched — colors only.
     ============================================================ */

  :root {
    color-scheme: dark !important;
    /* --color-ui-bg (#fff) is used ONLY as a background: panel bodies,
       the header, the "more →" scroll-fade gradient stops, the
       collapsed-panel bottom fade and the --nolink row hover. Remap it
       once instead of chasing each surface. --color-ui-bg--hover is a
       translucent light wash (rgba(241,243,245,.5)) painted on ranking
       rows, panel items and nav tabs on hover — it turned every hovered
       row into a grey glare block on dark. */
    --color-ui-bg: #14181d !important;
    --color-ui-bg--hover: #22272e !important;
    /* Every headline on the network is painted from this one token: the
       Narou brown #582b13 on yomou, the teal #0d6572 on the portal and
       mypage. Both are ~1.5-2:1 on dark. Remapping the token covers all
       of its consumers at once — page titles, card/cluster/aside
       headlines (incl. the aside bullet, which reads the token as a
       background-color), the ranking tabs' current item and the
       announce-bar telop — so a new consumer never lands unstyled. The
       per-selector rules further down stay as a belt-and-braces for the
       legacy markup that hardcodes the same hexes. */
    --color-text-headline: #e6c9a8 !important;
    --color-site-text-headline: #e6c9a8 !important;
  }

  /* ---- Base surfaces ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Soften every default light border into a subtle dark divider */
  * {
    border-color: #262c33 !important;
  }

  /* ...but a border IS the affordance (or the accent) for some elements.
     The blanket rule above flattens them, so restore the coloured edges:
     the active ranking/news tab's 3px underline (its ONLY active
     indicator), the checked radio/checkbox ring, and the signature cyan
     2px rules that top-and-tail every panel body. */
  .c-horizontalnav__item.is-active {
    border-bottom-color: #5fb0e6 !important;
  }
  .c-form__radio-input:checked,
  .c-form__checkbox-input:checked {
    border-color: #58a6ff !important;
  }
  .c-panel__body {
    border-top-color: rgba(24, 183, 205, 0.5) !important;
    border-bottom-color: rgba(24, 183, 205, 0.5) !important;
  }

  /* ============================================================
     Selected-state indicators
     The network marks the selected item four different ways and every
     one of them died on dark:
       - the yomou ranking period tabs (日間…累計) draw the current label
         AND a 4px underline from --color-text-headline — the token remap
         fixes the label, the blanket border reset above still flattens
         the underline;
       - the filter row below it (連載中…すべて) is a pill filled with
         --color-ui-bg, which we remap to the page bg — the pill vanished;
       - the section-heading accent bar is a border-left, also flattened;
       - the pager's current page draws a 3px bar from the brown
         --color-ui-accent (#823f1c, 2.1:1 — under the 3:1 floor for a
         non-text indicator);
       - the logged-in main-nav inverts the active item to a WHITE pill
         (--color-text--light) and our brown-nav rule paints its label
         cream on it (1.3:1). Give it a warm raised chip instead.
     Inactive siblings are plain links and stay accent blue.
     ============================================================ */
  .c-tabnav-1st__current,
  .c-tabnav-2nd__current {
    color: #e6c9a8 !important;
    -webkit-text-fill-color: #e6c9a8 !important;
  }
  .c-tabnav-1st__current {
    border-bottom-color: #e6c9a8 !important;
  }
  .c-tabnav-2nd__current {
    background-color: #21262d !important;
  }
  .c-card-cluster-title {
    border-left-color: #e6c9a8 !important;
  }
  .c-pager__item.is-current::after {
    background-color: #5fb0e6 !important;
  }
  .p-main-nav__item.is-active > a {
    background-color: #4a2e1c !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }

  /* ============================================================
     Icon-font glyphs (::before / ::after `content:`)
     These render as visible symbols but are NOT text nodes, so every
     color audit walks past them. Each kept a hardcoded legacy colour
     and went invisible on dark: the ranking dropdown caret and the
     search "series" chevrons at #333 (1.4:1), the mypage kebab at
     #666 (3.3:1). The ユーザ登録 pill is the mirror image — its icon
     stayed light-on-orange (1.7:1) while its label was darkened.
     ============================================================ */
  .p-ranktop-nav__category-name::after,
  .series_search__series::before,
  #main_search .p-icon::before {
    color: #c4cdd6 !important;
  }
  .c-dropdown__icon::before {
    color: #9aa3ad !important;
  }
  /* The kebab's flyout (mypage 設定 -> ブロックする / ミュートする) is a solid
     WHITE panel: --color-dropdown-bg-chips paints each bare <li>, and the
     wrapper is transparent, so no element-bg scan of the loaded page can see
     it — the node only exists once the kebab is clicked. The kebab itself
     grows an #eee hover disc (--color-dropdown-icon-bg-hover). */
  .c-dropdown__chips-group,
  .c-dropdown__chips-group li {
    background-color: #1c2128 !important;
  }
  .c-dropdown__icon:hover {
    background-color: #21262d !important;
  }
  .p-main-nav__item--useradd a,
  .p-main-nav__item--useradd .p-icon::before {
    color: #1a1109 !important;
  }
  /* The rank medal crown is a separate glyph from the number and keeps
     the site's own gold/silver/bronze; the bronze reads 3.7:1 on the
     card, so give the crowns the same refined medal tones as the digits. */
  .c-rank-place--1::before {
    color: #e3b341 !important;
  }
  .c-rank-place--2::before {
    color: #c9d1d9 !important;
  }
  .c-rank-place--3::before {
    color: #cd7f47 !important;
  }

  /* Generic light wrappers / panels -> elevated dark surface */
  .l-container,
  .l-main,
  .l-wrap,
  .l-jumbotron,
  .c-panel,
  .c-panel__body,
  .c-announce-box,
  .c-announce,
  .c-document,
  .searchkekka_box,
  .searchForm_box,
  .search_box,
  .index_box,
  .novel_bn,
  .p-footer-nav,
  .c-novel-attention,
  #novel_color,
  #container,
  #contents_main,
  #wrap {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Card surfaces (ranking cards, recommendations, bookmark bar,
     feedback form) -> elevated dark, opaque */
  .c-card,
  .p-ranktop-item,
  .p-recommend,
  .p-recommend__item,
  .p-bookmark-bar,
  .c-novel-feedback-form,
  .p-bookmark-modal,
  .c-modal,
  .c-modal__item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     Header / global navigation
     ============================================================ */
  .p-header,
  .l-header,
  .c-menu,
  .c-menu__body {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .p-header__logo,
  .p-header__description,
  .p-header__description-data,
  .p-header__count,
  .p-header__subnav-item,
  .p-header__subnav-item a {
    color: #c4cdd6 !important;
  }

  /* Main nav bar. Each site paints this from its own --color-ui-accent:
     brown #823f1c on yomou, brand cyan #18b7cd on the portal/mypage. One
     token cannot carry two hues, so the bar is unified on the classic Narou
     brown — a deliberate re-tune, and the only place the network's accent
     hue is not preserved. It keeps the identity and sits on dark without
     the glare a full-saturation cyan band would throw. */
  .p-main-nav,
  .p-sub-nav {
    background-color: #2a1a10 !important;
    border-color: #3a2517 !important;
  }

  .p-main-nav__item,
  .p-main-nav__item a,
  .p-main-nav__item-name,
  .p-sub-nav__item,
  .p-sub-nav__item a {
    color: #f0dccb !important;
  }

  .p-main-nav__item:hover,
  .p-main-nav__item a:hover {
    color: #ffffff !important;
  }

  /* "ユーザ登録" CTA pill (orange bg) — keep the brand orange but
     darken the label so it reads (was light-on-orange) */
  .p-main-nav__item--useradd,
  .p-main-nav__item--useradd .p-main-nav__item-name {
    color: #1a1109 !important;
  }

  /* Horizontal scroll-tab navs (ranking tabs, news/お知らせ tabs, genre
     sub-buttons) paint a "more →" scroll-fade via a ::after gradient that
     fades to WHITE — a bright strip at the right edge on dark. Remap the
     gradient stop to the page base so the fade reads dark. */
  .c-horizontalnav__mask::after,
  .c-horizontalnav-button__mask::after {
    background-image: linear-gradient(to left, #14181d, rgba(20, 24, 29, 0)) !important;
  }

  /* ============================================================
     Links & accents
     ============================================================ */
  a {
    color: #5fb0e6 !important;
  }
  a:hover {
    color: #9bd4ff !important;
  }

  /* Narou warm-orange link/title accent (search, novel titles):
     keep the orange identity, lift for dark legibility */
  .novel_h a,
  .noveltitle a,
  .c-novel-item__title a {
    color: #f0954a !important;
  }
  .novel_h a:hover,
  .noveltitle a:hover,
  .c-novel-item__title a:hover {
    color: #ffb877 !important;
  }

  /* Red menu accent (login / bookmark) -> refined warm red.
     The sticky header sits over the page, so keep its items opaque. */
  .c-menu__item,
  .c-menu__item--login,
  .c-menu__item--headnav,
  .c-menu__item--bookmark {
    background-color: #0d1117 !important;
    color: #ff7b72 !important;
  }
  .c-menu__item a {
    color: #ff7b72 !important;
  }

  /* ============================================================
     Reader — the novel chapter page (most important surface)
     Long-form Japanese text: soft off-white body, comfortable
     headings, dim-but-legible chapter metadata.
     ============================================================ */
  .p-novel,
  .p-novelmain,
  #novel_honbun,
  #novel_p,
  #novel_a {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  /* Body text — soft off-white, never pure white (reduces glare on
     long reading sessions). The chapter text is bare <p> elements
     inside .p-novel__text, each carrying the site's #444 — so target
     the paragraphs (and ruby furigana <rt>/<rp>) directly. */
  .p-novel__text,
  .js-novel-text,
  #novel_honbun,
  #novel_view,
  .novel_view,
  .p-novel__text p,
  .js-novel-text p,
  #novel_honbun p,
  #novel_view p,
  .novel_view p,
  .p-novel__text ruby,
  .p-novel__text rt,
  .p-novel__text rp,
  .js-novel-text rt,
  .js-novel-text rp {
    color: #c8d0d9 !important;
  }
  /* Furigana ruby annotations — slightly dimmer than the main line */
  .p-novel__text rt,
  .js-novel-text rt {
    color: #9aa3ad !important;
  }

  /* Chapter / story title */
  .p-novel__title,
  .p-novel__subtitle,
  .novel_subtitle,
  .c-title {
    color: #e6edf3 !important;
  }

  /* Episode number, dates, author line, update meta — muted but legible */
  .p-novel__number,
  .p-novel__author,
  .p-novel__date-published,
  .p-novel__date,
  .novel_writername,
  #novel_no,
  .koushinytime,
  .p-eplist__update,
  .c-pager__result-stats {
    color: #9aa3ad !important;
  }

  /* Story summary box */
  .p-novel__summary,
  #novel_ex {
    color: #b6c0ca !important;
  }

  /* Disclaimer/attention box — hardcoded #dd0000 red is harsh (~3.7:1)
     and illegible on dark; soften to the warm red that reads (≥4.5:1) */
  .c-novel-attention__warning {
    color: #ff7b72 !important;
  }

  /* New-impressions / reader comments block (bottom of chapter) —
     was #444 dark-on-dark */
  .p-new-impression,
  .p-new-impression__list,
  .p-new-impression__item {
    background-color: transparent !important;
  }
  .p-new-impression__headline,
  .p-new-impression__text,
  .p-new-impression__name {
    color: #c4cdd6 !important;
  }

  /* Reaction widget — the emoticon chips sit on a light #f1f3f5
     bar; darken it and lift the count text off link-blue */
  .p-reaction,
  .p-reaction__body,
  .js-reactionepisode_change,
  .p-reaction__emoticon {
    background-color: transparent !important;
  }
  .p-reaction__count {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Novel comments / reviews (novelcom.syosetu.com)
     The 感想一覧 / レビュー一覧 and error pages use a newer component
     family (.p-novelcom-* / .c-postedtext-*) with hardcoded light
     fills: the empty-state + error message boxes ship #fafafa, the
     感想絞り込み filter button is a light #dee2e6 pill, and each posted
     impression carries a light-grey #adb6bf エピソード badge. Neutralize
     the boxes and darken the light chips (their labels stay light). */
  .c-postedtext--noposts,
  .p-novelcom-text,
  .p-novelcom-text--error {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-novelcom-text__caution,
  .u-text-attention {
    color: #ff7b72 !important;
  }
  /* Light-grey control chips: the filter "全て表示" button and the per-
     comment エピソードN badge — dark elevated chip, keep the light label */
  .p-novelcom-header__narrowdown-button,
  .c-postedtext__target-info-episode {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* Posted impression/review meta (投稿者 line, dates) sits on transparent
     cards — keep it legible; poster-name links stay accent blue */
  .c-postedtext__poster,
  .c-postedtext__date,
  .c-postedtext__target-info {
    color: #9aa3ad !important;
  }
  .c-postedtext__poster a,
  .c-postedtext__target-info a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Story index (TOC) — episode list
     ============================================================ */
  .p-eplist,
  .index_box {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .p-eplist__chapter-title,
  .chapter_title {
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .p-eplist__sublist,
  .p-eplist__subtitle a,
  .subtitle a {
    color: #5fb0e6 !important;
  }
  .p-eplist__subtitle a:hover,
  .subtitle a:hover {
    color: #9bd4ff !important;
  }

  /* ============================================================
     Pager / chapter prev-next navigation
     ============================================================ */
  .c-pager,
  .c-pager__pager {
    background-color: transparent !important;
  }
  .c-pager__item,
  .c-pager__item a,
  .novel_bn a {
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }
  .c-pager__item a:hover,
  .novel_bn a:hover {
    color: #9bd4ff !important;
  }
  /* ...but the pager's dead ends (前の50作品へ on page 1, 次の… on the last)
     are <span class="is-disabled"> painted from --color-text--disable (#bbb).
     The rule above swallowed them, so a disabled control read exactly like a
     live link. Give them a muted grey that reads as "not clickable". */
  .c-pager__item.is-disabled,
  .c-pager__item.is-disabled a {
    color: #7d8590 !important;
  }

  /* ============================================================
     Sticky reader menu / layout-adjust (font-size) controls
     Must stay OPAQUE so chapter text never bleeds through.
     ============================================================ */
  .p-adjust-layout,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch,
  .p-adjust-layout__list,
  .p-adjust-layout__list-item,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__illustration,
  .c-hover-nav,
  .c-hover-nav__list {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .p-adjust-layout__title,
  .p-adjust-layout__switch,
  .p-adjust-layout__switch span,
  .p-adjust-layout__bottom-close,
  .p-adjust-layout__controller span,
  .c-hover-nav__title {
    color: #c4cdd6 !important;
  }
  .p-adjust-layout__title {
    color: #e6edf3 !important;
  }
  /* The layout on/off switch chips carry their own light fill (incl.
     the inner <span> that renders the toggle label) */
  .js-adjust-layout-on,
  .js-adjust-layout-off,
  .p-adjust-layout__controller,
  .p-adjust-layout__switch span,
  .js-adjust-layout-on span,
  .js-adjust-layout-off span {
    background-color: #1c2128 !important;
  }

  /* Floating up/down navigater pills (↓ to bottom / ↑ page-top) —
     were blue text on a pale #ccdddd pill */
  .c-navigater,
  .c-navigater--tobottom,
  .c-navigater--totop {
    background-color: #1c2128 !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }
  .c-navigater a {
    color: #9bd4ff !important;
  }

  /* Font-size / layout radio + checkbox labels */
  .c-form__radio-label,
  .c-form__checkbox-label {
    color: #c4cdd6 !important;
  }
  /* The reader's 配色/メニューバー controls (and the search filters) use
     appearance:none custom radios/checkboxes with a hardcoded #fff disc —
     they glare as bright white dots on the dark panel. Darken the control;
     the checked ::before keeps its accent-blue dot, so selection still reads. */
  .c-form__radio-input,
  .c-form__checkbox-input {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  /* Bookmark (しおり) button — incl. the disabled modifier which
     carries its own #fafafa fill */
  .c-bookmark-button,
  .c-bookmark-button--disabled,
  .c-bookmark-button.c-bookmark-button--disabled {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .c-bookmark-button.c-bookmark-button--disabled {
    color: #9aa3ad !important;
  }

  /* Modal action buttons / toast close (were blue on white/#ddd) */
  .c-button,
  .c-button--gray,
  .c-toast__close,
  .toaster_close {
    background-color: #21262d !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* ============================================================
     .c-button modifiers — the site's whole button semantics
     The bare .c-button is natively WHITE (--color-ui-button-bg), so the
     neutral chip above is right for it. But the network layers a modifier on
     top for every meaning, each painted from its own token, and the rule
     above flattened all of them into that same chip: the 404's only action
     and mypage's お気に入り (--primary #1b8ef3) became indistinguishable from
     a disabled control, and a destructive --delete would have read as a
     neutral one. Restore each meaning; the modifier out-specifies nothing,
     so these must come after .c-button, not before.
     ============================================================ */
  .c-button--primary {
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  /* Hover DEEPENS the blue rather than lightening it. #1f6feb already sits at
     4.6:1 under white, so the site's lighten-on-hover move would drop the
     label (and the button's icon glyph) to 3.3:1 — a hover-only contrast
     fail no load-time scan would ever see. */
  .c-button--primary:hover,
  .c-button--primary:focus,
  .c-button--primary:active {
    background-color: #1a5fd0 !important;
    color: #ffffff !important;
  }
  .c-button--delete {
    background-color: #da3633 !important;
    color: #ffffff !important;
    border-color: #da3633 !important;
  }
  /* Brand orange kept, label darkened — same treatment as the nav's
     ユーザ登録 pill (white-on-orange is 2.1:1) */
  .c-button--useradd {
    background-color: #ff922b !important;
    color: #1a1109 !important;
    border-color: #ff922b !important;
  }
  /* Natively transparent link-buttons, not filled chips */
  .c-button--minor,
  .c-button--outline {
    background-color: transparent !important;
    color: #5fb0e6 !important;
  }
  /* The "already done" state (e.g. already favourited) — must read inactive */
  .c-button--none-active {
    background-color: #30363d !important;
    color: #8b949e !important;
    border-color: #30363d !important;
  }

  /* Rating stars / point form */
  .p-novelpoint-form,
  .p-novelpoint-form__body {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  .c-novelpoint-star {
    color: #d6a44a !important;
  }
  .p-novelpoint-form__note {
    color: #9aa3ad !important;
  }
  /* Impression form note carries its own cream #fff9db fill — darken it
     and lift the text so it doesn't flash a bright band in the form */
  .c-novel-feedback-form__note {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }
  /* Rating-point form note link defaults to #0033cc (~2:1 on dark) — lift
     to the accent blue (the generic a{} rule is out-specified here) */
  .p-novelpoint-form__note a {
    color: #5fb0e6 !important;
  }

  /* ============================================================
     Page titles, rankings, sidebar links
     ============================================================ */
  .c-page-title,
  .c-page-title__text {
    color: #e6c9a8 !important;
  }
  .p-ranktop-nav,
  .p-ranktop-nav__category,
  .p-ranktop-nav__plate,
  .p-ranktop-nav__genreblock,
  .c-suplink {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }
  /* The genre-nav plate is a white card; give it an elevated dark
     surface so the genre links read on it */
  .p-ranktop-nav__plate {
    background-color: #1c2128 !important;
  }
  .p-ranktop-nav__smallgenre a,
  .p-ranktop-nav__smallgenrelist a {
    color: #5fb0e6 !important;
  }

