  }

  /* SNS share buttons - keep brand fills but ensure text legible */
  .c-sns__button {
    color: #e6edf3 !important;
  }

  /* R18 age-confirmation interstitial (年齢確認, the noc/mnlt/mid gate):
     a bare #modal whose heading (#444/#333) and body copy (#000) are
     dark-on-dark and all but invisible. Lift headings to amber and copy
     to body text; the Enter / exit links stay blue. */
  #modal h1,
  #modal h2 {
    color: #e6c9a8 !important;
  }
  #modal,
  #modal p {
    color: #c4cdd6 !important;
  }

  /* Ad / PR slots: neutral dark so blank slots don't flash white */
  .c-ad,
  .c-ad__item-horizontal,
  .c-pr {
    background-color: transparent !important;
  }

  /* ============================================================
     Error / 404 page (syosetu.com/<bad-url>)
     A full-width solid #fff panel; its teal #0d6572 heading would go
     dark-on-dark once the panel darkens, so lift it to the page amber.
     ============================================================ */
  .p-error-panel {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }
  .p-error-panel__heading {
    color: #e6c9a8 !important;
  }
  .p-error-panel__support-text {
    color: #c4cdd6 !important;
  }

  /* ============================================================
     Google Funding Choices consent dialog (.fc-consent-root)
     Rendered in the MAIN document on first visit — a solid white
     modal flashing over the dark page. Darken the panels and dividers;
     the blue CTA buttons keep their brand fill.
     ============================================================ */
  .fc-consent-root .fc-dialog,
  .fc-consent-root .fc-dialog-content,
  .fc-consent-root .fc-dialog-header,
  .fc-consent-root .fc-faq-contents,
  .fc-consent-root .fc-faq-icon,
  .fc-consent-root .fc-preference-container {
    background-color: #1c2128 !important;
  }
  .fc-consent-root .fc-dialog-headline,
  .fc-consent-root .fc-header-text,
  .fc-consent-root .fc-dialog p,
  .fc-consent-root .fc-dialog div,
  .fc-consent-root .fc-dialog span,
  .fc-consent-root .fc-dialog h1 {
    color: #c4cdd6 !important;
  }
  .fc-consent-root .fc-dialog a {
    color: #5fb0e6 !important;
  }
  /* The CMP ships its own !important rules at higher specificity, so the
     headline, the footer "List of partners" link and the FAQ disc must be
     matched selector-for-selector or they stay black-on-dark / white. */
  .fc-consent-root .fc-dialog .fc-header h1.fc-dialog-headline {
    color: #e6edf3 !important;
  }
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2,
  .fc-consent-root .fc-dialog .fc-footer a.fc-footer-link-v2:visited {
    color: #5fb0e6 !important;
  }
  .fc-consent-root .fc-faq-header .fc-faq-icon {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }
  .fc-consent-root .fc-faq-header .fc-faq-icon svg {
    fill: #c4cdd6 !important;
  }
  .fc-consent-root .fc-footer-buttons-divider,
  .fc-consent-root .fc-preference-divider {
    background-color: #2d333b !important;
  }
  /* Re-assert the label on the brand-blue CTAs (the broad text rule
     above would otherwise dim them). */
  .fc-consent-root .fc-button .fc-button-label {
    color: #ffffff !important;
  }
}
